package com.example.starter.domain;

/**
 * 航次状态：出港申报 → 进港报告 → 配额核销 → 结案，CLOSED 为终态。
 */
public enum VoyageStatus {

    /** 已出港（申报受理，允许提交渔捞日志）。 */
    DEPARTED,

    /** 已进港（卸渔报告受理，允许配额核销）。 */
    ARRIVED,

    /** 已核销（配额余额已扣减，允许结案）。 */
    SETTLED,

    /** 已结案（终态，不再接受业务变更，迟到日志仅记事件并转审查）。 */
    CLOSED
}

package com.example.starter.domain;

/**
 * 审查类型：兼捕超标、卸渔偏差、结案后迟到日志。
 */
public enum ReviewType {

    /** 兼捕保护鱼种占比超过 5% 触发的日志审查。 */
    BYCATCH,

    /** 进港卸渔量与日志累计量偏差超过 3% 触发的人工复核。 */
    DEVIATION,

    /** 航次结案后补交日志触发的迟到事件审查。 */
    LATE_LOG
}

package com.example.starter.domain;

/**
 * 审查状态：OPEN 待复核，RESOLVED 已复核（复核结论为最终口径）。
 */
public enum ReviewStatus {

    /** 待复核。 */
    OPEN,

    /** 已复核办结。 */
    RESOLVED
}

